    for user2 in users_list[i+1:]:
        user1_locations = [(date, label) for date, label in user_instances[user1] if label == 'location']
        user2_locations = [(date, label) for date, label in user_instances[user2] if label == 'location']

        user1_all_locations_after = all(parse_date(date) > cutoff_date for date, _ in user1_locations)
        user2_all_locations_after = all(parse_date(date) > cutoff_date for date, _ in user2_locations)

        if user1_all_locations_after and user2_all_locations_after:
            pairs.append((user1, user2))

print("Number of pairs:", len(pairs))
print("Pairs:", pairs)

# Sort pairs and output
pairs_sorted = sorted(pairs, key=lambda x: (x[0], x[1]))
print("Sorted pairs:")
for pair in pairs_sorted:
    print(f"{pair[0]}, {pair[1]}")
